    http_listener_name         = var.listener_name
    backend_address_pool_name  = var.backend_address_pool_name
    backend_http_settings_name = var.http_setting_name
  }

  tags = {
    environment = "example"
  }

  depends_on = [azurerm_public_ip.example]
